// RAW POINTER: Shared ownership, manual deletion risk
int* p_raw = new int(42);
int* p_copy = p_raw; // Ambiguous ownership

delete p_raw;       // Manual cleanup required
// delete p_copy;  // DANGER: Double deletion or leak risk

// UNIQUE_PTR: Exclusive ownership (RAII)
std::unique_ptr<int> p_safe = std::make_unique<int>(42);

// std::unique_ptr<int> p_fail = p_safe; // ERROR: Copy forbidden

// Ownership transfer must be explicit (move semantics)
std::unique_ptr<int> p_owner = std::move(p_safe);
// p_safe is now null
// Cleanup handled automatically when p_owner exits scope.

// Accessing the underlying pointer
int* raw_access = p_owner.get();
*raw_access = 50;
